import React, { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const SplashScreen = ({ onComplete }) => {
  const [showTagline, setShowTagline] = useState(false);
  const [showSubtitle, setShowSubtitle] = useState(false);
  const [showLine, setShowLine] = useState(false);

  useEffect(() => {
    // Staggered animation timeline
    const taglineTimer = setTimeout(() => setShowTagline(true), 800);
    const subtitleTimer = setTimeout(() => setShowSubtitle(true), 1200);
    const lineTimer = setTimeout(() => setShowLine(true), 1600);
    const completeTimer = setTimeout(() => onComplete(), 3200);

    return () => {
      clearTimeout(taglineTimer);
      clearTimeout(subtitleTimer);
      clearTimeout(lineTimer);
      clearTimeout(completeTimer);
    };
  }, [onComplete]);

  return (
    <motion.div
      className="fixed inset-0 z-[9999] flex items-center justify-center overflow-hidden"
      style={{ background: "linear-gradient(135deg, #0d0405 0%, #1a080a 50%, #2a1015 100%)" }}
      exit={{ opacity: 0 }}
      transition={{ duration: 1.2, ease: "easeInOut" }}
    >
      {/* Animated Background Elements */}
      <div className="absolute inset-0 overflow-hidden">
        {/* Golden particles */}
        {[...Array(20)].map((_, i) => (
          <motion.div
            key={i}
            className="absolute w-1 h-1 rounded-full"
            style={{
              background: "radial-gradient(circle, #d4af37 0%, transparent 70%)",
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
            }}
            animate={{
              y: [0, -100, 0],
              opacity: [0, 1, 0],
              scale: [0, 1.5, 0],
            }}
            transition={{
              duration: 3 + Math.random() * 2,
              repeat: Infinity,
              delay: Math.random() * 3,
              ease: "easeInOut",
            }}
          />
        ))}

        {/* Floating geometric shapes */}
        {[...Array(5)].map((_, i) => (
          <motion.div
            key={`shape-${i}`}
            className="absolute border opacity-20"
            style={{
              width: 100 + i * 40,
              height: 100 + i * 40,
              borderColor: "#d4af37",
              borderRadius: i % 2 === 0 ? "50%" : "0",
              left: `${10 + i * 20}%`,
              top: `${10 + i * 15}%`,
            }}
            animate={{
              rotate: [0, 360],
              scale: [1, 1.1, 1],
            }}
            transition={{
              duration: 20 + i * 5,
              repeat: Infinity,
              ease: "linear",
            }}
          />
        ))}

        {/* Radial gradient pulse */}
        <motion.div
          className="absolute inset-0"
          style={{
            background: "radial-gradient(circle at center, rgba(212,175,55,0.15) 0%, transparent 70%)",
          }}
          animate={{
            scale: [1, 1.2, 1],
            opacity: [0.3, 0.6, 0.3],
          }}
          transition={{
            duration: 4,
            repeat: Infinity,
            ease: "easeInOut",
          }}
        />
      </div>

      {/* Main Content */}
      <div className="relative text-center px-8">
        {/* Crown Icon */}
        <motion.div
          initial={{ opacity: 0, scale: 0, rotate: -180 }}
          animate={{ opacity: 1, scale: 1, rotate: 0 }}
          transition={{ duration: 1, ease: [0.34, 1.56, 0.64, 1] }}
          className="mb-6"
        >
          <motion.svg
            width="48"
            height="48"
            viewBox="0 0 24 24"
            fill="none"
            stroke="#d4af37"
            strokeWidth="1.5"
            animate={{
              filter: [
                "drop-shadow(0 0 5px rgba(212,175,55,0.5))",
                "drop-shadow(0 0 20px rgba(212,175,55,0.8))",
                "drop-shadow(0 0 5px rgba(212,175,55,0.5))",
              ],
            }}
            transition={{ duration: 2, repeat: Infinity }}
          >
            <path d="M2 17L5 7L9 12L12 4L15 12L19 7L22 17H2Z" strokeLinecap="round" strokeLinejoin="round" />
            <path d="M2 17H22V20C22 21 21 22 20 22H4C3 22 2 21 2 20V17Z" strokeLinecap="round" strokeLinejoin="round" />
          </motion.svg>
        </motion.div>

        {/* Brand Name - Main Animation */}
        <div className="relative">
          {/* Letter by letter animation */}
          <motion.h1
            className="serif tracking-[0.3em] mb-2"
            style={{
              fontSize: "clamp(48px, 12vw, 100px)",
              fontWeight: 400,
              background: "linear-gradient(100deg, #8b6914 0%, #d4af37 25%, #f4d77a 45%, #ffeaa7 50%, #f4d77a 55%, #d4af37 75%, #8b6914 100%)",
              backgroundSize: "250% 100%",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              backgroundClip: "text",
              animation: "shimmer 3s linear infinite",
            }}
            initial={{ opacity: 0, letterSpacing: "1em" }}
            animate={{ opacity: 1, letterSpacing: "0.3em" }}
            transition={{ duration: 1.5, ease: [0.25, 0.46, 0.45, 0.94] }}
          >
            {"D SAJAWAT".split("").map((char, i) => (
              <motion.span
                key={i}
                initial={{ opacity: 0, y: 50 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{
                  delay: 0.3 + i * 0.08,
                  duration: 0.6,
